html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>您已安全 · 真人写实横屏</title><style>*{box-sizing:border-box}body{margin:0;background:#10171b;color:#e6e9eb;font:16px system-ui;max-width:1240px;padding:28px;margin:auto}h1{font-size:26px;margin:0 0 8px}p{color:#a7b1b9}.player{container-type:inline-size;position:relative;background:#000;aspect-ratio:16/9;width:min(100%,calc(max(220px,100vh - 270px) * 16 / 9));margin-inline:auto}video{width:100%;height:100%;display:block}.cue{position:absolute;bottom:9%;left:7%;right:7%;text-align:center;color:white;font-size:clamp(16px,3cqw,32px);line-height:1.45;text-shadow:0 2px 5px #000,1px 1px 1px #000;pointer-events:none;white-space:pre-line}button,select,a{font:inherit}button,select{background:#27343b;color:#eef;padding:9px;border:1px solid #485962;border-radius:6px}a{color:#9fd4db}.tools{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.note{font-size:14px}.status{font-variant-numeric:tabular-nums}</style><h1>您已安全</h1><p>六分钟原版 · 正常自然光真人写实 · 16:9 · 无音轨 · 外挂字幕</p><div class="player"><video id="film" controls muted preload="auto" playsinline src="you-are-safe-photoreal-6min-v1.mp4"></video><div id="cue" class="cue"></div></div><div class="tools"><button id="play">播放</button><button id="captions">隐藏外挂字幕</button><select id="chapters" aria-label="选择场景"></select><a href="you-are-safe-photoreal-6min-v1.mp4" download>下载MP4</a><a href="you-are-safe.zh-CN.srt" download>下载SRT</a><a href="you-are-safe.zh-CN.vtt" download>下载VTT</a></div><p class="status" id="status"></p><p class="note">视频文件无音轨、无烧录字幕。此页字幕为外挂展示，可关闭。7.5字/秒为文字估时，包含明确的情绪留白；尚未对齐你后续的真实配音。</p><script>const cues=__CUES__,shots=__SHOTS__,fps=30;const v=document.querySelector('#film'),el=document.querySelector('#cue'),sel=document.querySelector('#chapters'),status=document.querySelector('#status');let show=true;window.playbackQa={started:false,ended:false};shots.forEach(s=>{let o=document.createElement('option');o.value=s.start_frame/fps;o.textContent=(s.start_frame/fps).toFixed(1)+'s · '+s.title;sel.append(o)});sel.onchange=()=>{v.currentTime=+sel.value};document.querySelector('#play').onclick=()=>v.paused?v.play():v.pause();document.querySelector('#captions').onclick=()=>{show=!show;document.querySelector('#captions').textContent=show?'隐藏外挂字幕':'显示外挂字幕';tick()};v.onplay=()=>{window.playbackQa.started=true;document.querySelector('#play').textContent='暂停'};v.onpause=()=>document.querySelector('#play').textContent='播放';v.onended=()=>window.playbackQa.ended=true;function wrapCue(t){if(t.length<=24)return t;let a=[];for(let i=0;i<t.length;i++)if('，。；！？'.includes(t[i])&&i+1>=6&&i+1<=t.length-6)a.push(i+1);let cut=a.length?a.sort((a,b)=>Math.abs(a-t.length/2)-Math.abs(b-t.length/2))[0]:Math.floor(t.length/2);return t.slice(0,cut)+'\\n'+t.slice(cut)}function tick(){let f=Math.floor(v.currentTime*fps+0.0001),c=cues.find(c=>f>=c.start_frame&&f<c.end_frame_exclusive);el.textContent=show&&c?wrapCue(c.text):'';status.textContent=v.currentTime.toFixed(2)+' / '+(isFinite(v.duration)?v.duration.toFixed(2):'—')+' 秒';window.playbackQa.currentTime=v.currentTime;window.playbackQa.duration=v.duration;window.playbackQa.ended=v.ended;requestAnimationFrame(tick)}requestAnimationFrame(tick);</script></html>'''.replace('__CUES__',cues).replace('__SHOTS__',shots)
